record.field:
# Check if multiple records are selected
if len(records) == 1:
    # Single record - open normal cancel wizard
    action = {
        'name': 'Cancel Material Requisition',
        'type': 'ir.actions.act_window',
        'res_model': 'material.requisition.cancel.wizard',
        'view_mode': 'form',
        'target': 'new',
        'context': {'active_model': 'material.requisition', 'active_id': records.id}
    }
else:
    # Multiple records - show bulk cancel wizard
    cancellable_records = records.filtered(lambda r: r.state in ['draft', 'submitted', 'waiting_for_approval'])

    if not cancellable_records:
        raise UserError("No requisitions can be cancelled. Only draft, submitted, or waiting for approval requisitions can be bulk cancelled.")

    skipped = len(records) - len(cancellable_records)

    # Continue even if some were skipped, don't use notify_warning
    action = {
        'name': f'Bulk Cancel {len(cancellable_records)} Requisitions',
        'type': 'ir.actions.act_window',
        'res_model': 'material.requisition.bulk.cancel.wizard',
        'view_mode': 'form',
        'target': 'new',
        'context': {
            'active_model': 'material.requisition',
            'active_ids': cancellable_records.ids,
            'bulk_cancel': True,
            'skipped_count': skipped  # Optional: use this in wizard
        }
    }
